(self.webpackChunkroot=self.webpackChunkroot||[]).push([[1253,1786],{"./node_modules/.pnpm/@mdx-js+react@3.1.1_@types+react@18.3.3_react@19.2.7/node_modules/@mdx-js/react/index.js"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>MDXProvider,useMDXComponents:()=>useMDXComponents});var react=__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/index.js");const emptyComponents={},MDXContext=react.createContext(emptyComponents);function useMDXComponents(components){const contextComponents=react.useContext(MDXContext);return react.useMemo(function(){return"function"==typeof components?components(contextComponents):{...contextComponents,...components}},[contextComponents,components])}function MDXProvider(properties){let allComponents;return allComponents=properties.disableParentContext?"function"==typeof properties.components?properties.components(emptyComponents):properties.components||emptyComponents:useMDXComponents(properties.components),react.createElement(MDXContext.Provider,{value:allComponents},properties.children)}},"./stories/22.NightingaleBoxplotTrack/NightingaleBoxplotTrack.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/index.js");var jsx_runtime=__webpack_require__("./node_modules/.pnpm/react@18.3.1/node_modules/react/jsx-runtime.js"),mdx_react_shim=__webpack_require__("./node_modules/.pnpm/@storybook+addon-docs@8.6.18_@types+react@18.3.3_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1_/node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"),dist=__webpack_require__("./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist/index.mjs");var nightingale_base_element=__webpack_require__("./packages/nightingale-new-core/src/nightingale-base-element.md"),README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withDimensions/README.md"),withHighlight_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withHighlight/README.md"),withManager_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withManager/README.md"),withMargin_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withMargin/README.md"),withPosition_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withPosition/README.md"),withResizable_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withResizable/README.md"),withZoom_README=__webpack_require__("./packages/nightingale-new-core/src/mixins/withZoom/README.md");function _createMdxContent(props){const _components={p:"p",...(0,mdx_react_shim.useMDXComponents)(),...props.components};return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(dist.Meta,{title:"Components/Tracks/Boxplot Track/Readme"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:'# nightingale-boxplot-track\n\n[![Published on NPM](https://img.shields.io/npm/v/@nightingale-elements/nightingale-boxplot-track.svg)](https://www.npmjs.com/package/@nightingale-elements/nightingale-boxplot-track)\n\nNightingale boxplot track component is used to display the distribution of a variable at each sequence position using boxplots. It allows displaying multiple distribution datasets, rendered side-by-side at each sequence position.\n\nMost of the rendering is implemented via HTML canvas, but some non-critical parts are implemented via SVG (e.g. highlights).\n\n## Usage\n\n```html\n<nightingale-boxplot-track\n    id="track"\n    width="600" height="200"\n    length="3"\n    y-min="0" y-max=""\n    show-axis\n    show-nested-highlights\n    zoomed-out-outline="whiskers"\n    column-gap="0.2" box-gap="0.1" whisker-width="0.6" outlier-jitter-width="0.4"\n    outlier-radius="2"\n    zoom-transition-range="4-5"\n    margin-left="30" margin-right="10" margin-top="5" margin-bottom="5" margin-color="#ffffffee"\n    highlight-event="onmouseover" highlight-color="#eb3bff22"\n    use-ctrl-to-zoom\n></nightingale-boxplot-track>\n```\n\n#### Setting the data through property\n\n```typescript\nawait customElements.whenDefined(\'nightingale-boxplot-track\');\nconst track = document.getElementById(\'track\');\nif (track) {\n    // Showing 2 datasets on a sequence of 3 amino acids:\n    (track as any).data = [\n        {\n            name: \'Blue dataset\',\n            color: \'#0088ff\',\n            positions: [\n                { position: 1, values: [0.2, 0.5, 0.7, 0.9] },\n                { position: 2, values: [0.1, 0.3, 0.5, 0.8] },\n                { position: 3, values: [0.0, 0.2, 0.6, 0.8] },\n            ],\n        },\n        {\n            name: \'Orange dataset\',\n            color: \'#ff8800\',\n            positions: [\n                { position: 1, values: [0.1, 0.3, 0.5, 0.8] },\n                { position: 2, values: [0.0, 0.2, 0.6, 0.8] },\n                { position: 3, values: [0.2, 0.5, 0.7, 0.9] },\n            ],\n        },\n    ];\n}\n```\n\nThe `data` property expects a value of type `BoxplotData` - an array of datasets, where each dataset has the following structure:\n\n```typescript\n{\n    name: string,\n    color?: string,\n    positions: Array<{\n        position: number,\n        values: Array<number>,\n    }>,\n}\n```\n\nThe component will compute the median, quartiles, whiskers, and outliers from the values array for each position.\n\n## Visualization description\n\nThe components displays a boxplot at each sequence position where data have been provided (or multiple boxplots if there are multiple dataset).\nEach boxplot shows the following data:\n\n```\n   •     ╮┄┄┄┄┄┄┄┄ Maximum\n   ••    │ Outliers high\n  ••     ╯\n ──┬──   - Whisker high (highest value <= Q3 + 1.5 * IQR)\n   │\n   │\n┌──┴──┐  - Box high = Q3\n┝━━━━━┥  - Median\n│     │\n└──┬──┘  - Box low = Q1\n   │\n ──┴──   - Whisker low (lowest value >= Q1 - 1.5 * IQR)\n  •••    ╮\n    •    │ Outliers low\n  ••     ╯┄┄┄┄┄┄┄┄ Minimum\n```\n\n\\* Q1 = lower quartile, Q3 = upper quartile, IQR = Q3 - Q1 = interquartile range.\n\n### "zoomed-out" visualization\n\nWhen the view becomes too much zoomed-out and boxplots become poorly visible, the component will switch from boxplot visualization to simplified "zoomed-out" visualization. This visualization shows the median at each position in darker color, and optionally a lighter shaded outline representing extremes or whisker range or box range, depending on the `zoomed-out-outline` attribute (default: whisker range). The `zoom-transition-range` attributes controls when exactly this transition happens. If there are multiple datasets, they are overlaid on one another, being distinguishable by their color (rather then displayed side-by-side as boxplots).\n\n### Downsampling\n\nWhen the view becomes over more zoomed-out (column width < 1 screen pixel), the component will downsample the displayed simplified visualization data. This is done to ensure performance for very long sequences and shouldn\'t be visually noticeable.\n\n## API Reference\n\n### Attributes\n\n#### `y-min?: number, y-max?: number`\n\nBottom and top limit for the Y-axis. If either of these is not set, it will be inferred from the data (minimum/maximum of all data values).\n\n#### `show-axis?: boolean (default: false)`\n\nTurn on or off displaying the vertical axis.\n\nThe axis is rendered in the left margin of the component. The margin attributes must be set accordingly to provide enough space for the axis (e.g. `margin-left="30"`).\n\n#### `show-nested-highlights?: boolean (default: false)`\n\nTurn on or off displaying nested hightlights. Nested hightlights indicate the selected subcolumn (dataset) within the highlighted column (sequence position). This applies only when multiple datasets are displayed.\n\n#### `zoomed-out-outline?: "extremes" | "whiskers" | "box" | "none" (default: "whiskers")`\n\nChoose what kind of data is shown as the shaded outline in the simplified zoomed-out view (in addition to the darker lines showing median).\n\n-   `"extremes"` - the outline covers the range between minimum and maximum;\n-   `"whiskers"` - the outline covers the same range as the whiskers in the boxplot;\n-   `"box"` - the outline covers the same range as the box in the boxplot (quartiles);\n-   `"none"` - no outline is rendered.\n\n#### `column-gap?: number (default: 0.2)`\n\nWidth of the gap between displayed columns, relative to the base width (width of one sequence position).\n\n(= _Column gap_ / _Base width_ in the figure below)\n\n#### `box-gap?: number (default: 0.1)`\n\nWidth of the gap between boxes within a column, relative to the column width divided by the number of datasets (= _Box gap_ / (_Column width_ / _N datasets_) = _Box gap_ / (_Box width_ + _Box gap_) in the figure below).\n\n#### `whisker-width?: number (default: 0.6)`\n\nBoxplot whisker width, relative to the box width (= _Whisker width_ / _Box width_ in the figure below).\n\n#### `outlier-jitter-width?: number (default: 0.4)`\n\nWidth of random noise added to the X-position of outliers, relative to the box width (= _Outlier jitter width_ / _Box width_ in the figure below).\n\n#### `outlier-radius?: number (default: 2)`\n\nRadius of the circles used to render outliers, in CSS pixels.\n\n#### `zoom-transition-range?: string (default: "4-5")`\n\nBase width(s), in CSS pixels, where the transition from "zoomed-out" simplified visualization to "zoomed-in" boxplot visualization happens.\n\n`zoom-transition-range` can be either one number (for a sharp transition, e.g. `"4"`) or a hyphen-separated range (for a smooth transition, e.g. `"4-5"`).\n\nIf there are multiple datasets, this width(s) will be multiplied by the number of datasets, to compensate for narrower space for each dataset.\n\n-   Use `"0"` to always show "zoomed-in" boxplot visualization. (This is not recommended, as it will prevent downsampling and may cause performance issues. However, you can use sufficiently small values, such as `"0.5-1"`, to achieve the same goal without performance issues).\n\n*   Use `"Infinity"` to always show "zoomed-out" visualization.\n\n#### Overview of width measurements\n\n(2 sequence positions with 2 datasets)\n\n```\n   Seq. position 1       Seq. position 2\n<────────────────────><────────────────────> Base width\n┄><────────────────><┄┄><────────────────><┄ Column width, Column gap\n  ><─────><><─────><    ><─────><><─────><   Box width, Box gap*\n    <───>    <───>        <───>    <───>     Whisker width\n    ──┬──    ──┬──        ──┬──    ──┬──\n   ┌──┴──┐  ┌──┴──┐      ┌──┴──┐  ┌──┴──┐\n   │     │  │     │      │     │  │     │\n   ┝━━━━━┥  ┝━━━━━┥      ┝━━━━━┥  ┝━━━━━┥\n   │     │  │     │      │     │  │     │\n   └──┬──┘  └──┬──┘      └──┬──┘  └──┬──┘\n    ──┴──    ──┴──        ──┴──    ──┴──\n     •••      • •           ••      • •\n       •      •            ••        •\n     <─>      <─>          <─>      <─>      Outlier jitter width\n```\n\n\\* Full _Box gap_ between the boxes in a column, 1/2 _Box gap_ before the first and after the last box in a column\n\n### Events\n\nAs `nightingale-boxplot-track` implements from `withZoom` and `withHighlight`, it will respond to zooming changes, highlight events, and emit events when interacting with boxplots (helpful if you want to display tooltips, integrate with other components etc.).\n\nWhen the user clicks on or hovers over the component, the component emits a `CustomEvent` with type `"change"` and with `detail` of the following structure:\n\n```typescript\n{\n    eventType: "mouseover" | "mouseout" | "click",\n    parentEvent?: Event,\n    feature?: {\n        type: "boxplot",\n        /** Position in the sequence */\n        position: number,\n        /** Data for the boxplot at this position from all datasets (one item for each dataset) */\n        data: Array<{\n            /** Common properties of the whole dataset */\n            dataset: {\n                name: string,\n                color: string,\n            },\n            /** Boxplot data at this position */\n            datum?: {\n                /** Position in the sequence */\n                position: number,\n                /** All values of the independent variable at this position */\n                values: Float32Array,\n                median: number,\n                boxLow: number,\n                boxHigh: number,\n                whiskerLow: number,\n                whiskerHigh: number,\n                minimum: number,\n                maximum: number,\n                outliersLow: Float32Array,\n                outliersHigh: Float32Array,\n            },\n        }>,\n        /** Index into `data`, indicates which dataset is being pointed at */\n        datasetIndex: number,\n    } | null,\n}\n```\n\n### Other attributes and properties\n\nThis component inherits from `NightingaleElement`.\n\nThe component implements the following mixins: `withCanvas`, `withManager`, `withZoom`, `withResizable`, `withMargin`, `withPosition`, `withDimensions`, `withHighlight`.\n'}),"\n",(0,jsx_runtime.jsx)("hr",{}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Mixins"}),"\n",(0,jsx_runtime.jsx)("p",{children:(0,jsx_runtime.jsx)(_components.p,{children:"This component implement the following mixins, and therefore it includes their\nattributes and properties."})}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withHighlight_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withManager_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withMargin_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withPosition_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withResizable_README}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:withZoom_README}),"\n",(0,jsx_runtime.jsx)("h2",{children:"Parent Class"}),"\n",(0,jsx_runtime.jsx)(dist.Markdown,{children:nightingale_base_element})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,mdx_react_shim.useMDXComponents)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent(props)}},"./node_modules/.pnpm/@storybook+addon-docs@8.6.18_@types+react@18.3.3_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1_/node_modules/@storybook/addon-docs/dist/shims/mdx-react-shim.mjs"(__unused_webpack_module,__webpack_exports__,__webpack_require__){"use strict";__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{MDXProvider:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.MDXProvider,useMDXComponents:()=>_mdx_js_react__WEBPACK_IMPORTED_MODULE_0__.useMDXComponents});var _mdx_js_react__WEBPACK_IMPORTED_MODULE_0__=__webpack_require__("./node_modules/.pnpm/@mdx-js+react@3.1.1_@types+react@18.3.3_react@19.2.7/node_modules/@mdx-js/react/index.js")},"./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+blocks@8.6.18_react-dom@19.2.7_react@19.2.7__react@19.2.7_storybook@8.6.18_p_8f9138463b79afe28a3a362748d078e4/node_modules/@storybook/blocks/dist sync recursive",module.exports=webpackEmptyContext},"./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/components sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/components sync recursive",module.exports=webpackEmptyContext},"./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/theming sync recursive"(module){function webpackEmptyContext(req){var e=new Error("Cannot find module '"+req+"'");throw e.code="MODULE_NOT_FOUND",e}webpackEmptyContext.keys=()=>[],webpackEmptyContext.resolve=webpackEmptyContext,webpackEmptyContext.id="./node_modules/.pnpm/@storybook+core@8.6.18_prettier@3.2.5_storybook@8.6.18_prettier@3.2.5_supports-color@8.1.1__supports-color@8.1.1/node_modules/@storybook/core/dist/theming sync recursive",module.exports=webpackEmptyContext},"./packages/nightingale-new-core/src/mixins/withDimensions/README.md"(module){"use strict";module.exports="### withDimensions\n\nIt adds `width` and `height` as parameters.\n\n##### Options\n\nWhen instancing this mixin, the function can receive an object with options for default values:\n\n```javascript\n{\n  width?: number;\n  height?: number;\n}\n```\n\n##### Attributes\n\n###### `height: number (default undefined)`\n\nThe height of the track as a numeric value in pixels.\n\n###### `width: number (default undefined)`\n\nThe width of the track as a numeric value in pixels.\n"},"./packages/nightingale-new-core/src/mixins/withHighlight/README.md"(module){"use strict";module.exports="### withHighlight\n\nIt adds the necessary properties to a component that is using highlight. Notice, this doesn't render the anything in your component. Rather it takes care of setting the parameters and react when they changes.\n\nA component that wants to render a highlight needs to implement the `updateHighlight` method which will be called when the highlight attribute is updated.\n\nIt adds `highlight` and `highlight-color` as attributes.\n\n##### Attributes\n\n###### `highlight: string | null (default null)`\n\nA string representing a set of regions that required to be highilghted. it is a comma separated list of regions and each region, has start and end separated by `:`.\n\nFor example, `1:5,10:20` represents 2 regions. The first region goes from position `1` to `5`, and the second region goes from `10` to `20`.\n\n`null` represents no region needs to be highlighted.\n\n###### `highlight-color: string (default #FFEB3B66)`\n\nThe color to use when rendering the highlight. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Properties\n\n###### `fixedHighlight: string | null (default null)`\n\nWorks similar to the `highlight` attribute. The idea is to have a way to define a region that is always highlighted independently of the changes of `highlight`. Used in interpro to highlight the coverage of a chain in a protein.\n\n##### Methods\n\n###### ` protected updateHighlight()`\n\nThis method is called when any the highlight regions changed. In this mixin is just a place holder, but a component using `withHighlight` is expected to implement the highlight rendering logic by overwriting this method.\n"},"./packages/nightingale-new-core/src/mixins/withManager/README.md"(module){"use strict";module.exports="### withManager\n\nAdds the property `manager` which is set in `connectedCallback` as the closest `nigthingale-manager` element, and then it register the component in the manager.\n\n##### Properties\n\n###### `manager?: HTMLElement | null;`\n\nReference to the closest `nighhtingale-manager` component.\n"},"./packages/nightingale-new-core/src/mixins/withMargin/README.md"(module){"use strict";module.exports="### withMargin\n\nDefines attributes for the margin of the component. it has a helper method to render the margins on a given d3 selection; this method is not automatically called, and it's the component resposability to invoke it at the right time.\n\n##### Mixins\n\nImplements the mixin `withDimensions` to be able to calculate values with `width` and `height`.\n\n##### Attributes\n\n###### `margin-top: number (default: 0)`\n\nTop margin in pixels\n\n###### `margin-bottom: number (default: 0)`\n\nBottom margin in pixels\n\n###### `margin-left: number (default: 10)`\n\nLeft margin in pixels\n\n###### `margin-right: number (default: 10)`\n\nRight margin in pixels\n\n###### `margin-color?: string | null (default: #FFFFFFDD)`\n\nThe color to use when rendering the margin. It follows the web standard defined in https://developer.mozilla.org/en-US/docs/Web/CSS/color_value\n\n##### Methods\n\n###### `getWidthWithMargins(): number`\n\nSubstract the defined margins(left and right) from the width.\n\n###### `getHeightWithMargins()`\n\nSubstract the defined margins(top and bottom) from the height.\n\n###### `renderMarginOnGroup( g?: Selection<SVGGElement, unknown, HTMLElement | SVGElement | null, unknown>): void`\n\nGiven a D3 selection it renders rectangles in the position of the margins, filling them with `margin-color`\n"},"./packages/nightingale-new-core/src/mixins/withPosition/README.md"(module){"use strict";module.exports="### withPosition\n\nAdds the attributes required for the position to locate the track.\n\n##### Attributes\n\n###### `display-start?: number (default 1)`\n\nPosition on the sequence where the track should start rendering from.\n\n###### `display-end?: number (default -1)`\n\nPosition on the sequence where the track should end its rendering. The default `-1` represents the end of the sequence.\n\n###### `length?: number (default 0)`\n\nLength of the sequence\n"},"./packages/nightingale-new-core/src/mixins/withResizable/README.md"(module){"use strict";module.exports="### withResizable\n\nUses a `ResizeObserver` to detect changes in the size of the component, and sets the `width` and `height` propertes.\n\n##### Attributes\n\n###### `min-height: number (default 10)`\n\nThe minimum height of the track as a numeric value in pixels.\n\n###### `min-width: number (default 10)`\n\nThe minimum width of the track as a numeric value in pixels.\n\n##### Methods\n\n###### ` protected onDimensionsChange(): void`\n\nOverride this method if there is anything to be done when the dimensions change after the component is resized.\n\n##### Mixins\n\nImplements the mixin `withDimensions` to be able to set the values of `width` and `height` of the component.\n"},"./packages/nightingale-new-core/src/mixins/withZoom/README.md"(module){"use strict";module.exports="### withZoom\n\nAdds the zoom capabilities to a track. It creates a D3 scale between the sequence coordinates (from 1 to the length of the sequence) and the space on screen( from 0 to the width of the component).\n\nThe scale get updated either by a zoom event over the component, or by a change on the attributes: `display-start` or `display-end`.\n\nOnce the scale gets updated the `super.render()` method is invoked triggering a rerender in your component.\n\n##### Mixins\n\nImplements the following mixins:\n\n- `withDimensions` to be able to calculate values with `width` and `height`.\n- `withMargin` to consider the lost margin space in the margins\n- `withPosition` to re calculate the scale whe displayed coordinates(i.e. `display-start` and `display-end`) change.\n\n##### Properties\n\n###### `xScale?: ScaleLinear<number, number>;`\n\nThe scale function for the X axis where on the initial state, the domain goes from `1` to the lenght of the sequence, and the range goes from `0` to the width of the SVG component.\n\nThe domain gets updated when the zoom and panning levels change.\n\nThe range gets updated when the width is changed.\n\n###### `svg?: Selection< SVGSVGElement, unknown, HTMLElement | SVGElement | null, unknown >`;\n\nThe D3 selection to the root `svg` element rendered in the component. The zooming events will be bind to this element.\n\n##### Methods\n\n###### `getSingleBaseWidth(): number`\n\nUses the current scale to calculate the width of a single base on the sequence.\n\n###### `getXFromSeqPosition(position: number): number`\n\nGets the coordinates in the SVG for a given position in the sequence\n\n###### `getSeqPositionFromX(position: number): number`\n\nInverse to `getXFromSeqPosition`\n\n###### `updateScaleDomain(): void`\n\nCall this method to trigger an update on the scale. This only will have an effect if `length`, `width` or `margin-*` have been modified manually.\n\n##### Mixins\n\nImplements the mixins: `withMargin`, `withPosition`, `withResizable`, and `withDimensions`\n"},"./packages/nightingale-new-core/src/nightingale-base-element.md"(module){"use strict";module.exports="### NightingaleElement\n\nThe base element for any Nightingale component. Inherits from [LitElement](https://lit.dev/docs/api/LitElement/).\n\nAny logic that should be shared for all the components should be included here. Currently the only thing is doing, is setting the render root of the components in the element itself, instead of shadowDOM, the Lit element default.\n"}}]);
//# sourceMappingURL=22-NightingaleBoxplotTrack-NightingaleBoxplotTrack-mdx.2a7f1031.iframe.bundle.js.map